// productlogolovartstyle — generated by the Thinking Logos playground.
// State: waiting. Paste this file in and import it; it needs only React.

import { useEffect, useRef, useState } from "react";
import type { RefObject } from "react";

/** Minimal local types — the copied file depends on nothing. */
interface ModeOpts {
  [key: string]: number | undefined;
}
interface LogoPointSet {
  readonly n: number;
  readonly p: Float32Array;
  readonly e: Float32Array;
}
type SeatMap = Uint32Array;
interface LogoBinding {
  readonly points: LogoPointSet;
  readonly seats: SeatMap;
}
type ModeFrame = (size: number, t: number, opts: ModeOpts, logo?: LogoBinding) => OrbFrame;

interface Dot {
  x: number;
  y: number;
  z: number;
  r: number;
  /** Ink value: 0 = darkest ink on paper. Mirrored on dark themes. */
  white: number;
  a?: number;
  /**
   * How much of the brand tint this dot carries, 0 = neutral grey, 1 = full
   * colour. Defaults to 1, so every mode that ignores it is unaffected.
   *
   * It exists so a state can say something with colour that it cannot say
   * with position: in `working`, a carrier in transit is grey cargo and
   * gains the brand's colour as it seats into the mark. Untinted renders
   * ignore it entirely — greyscale blended toward greyscale is greyscale —
   * which keeps the geometry identical either way.
   */
  k?: number;
}

/** A stroked edge between two projected points (the `connecting` web). */
interface Line {
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  /** Ink value, same convention as `Dot.white`. */
  white: number;
  a?: number;
  w: number;
}

/**
 * One rendered instant: a complete, final set of draw instructions.
 * `dots` is already z-sorted into draw order and radius-clamped; `lines`
 * are drawn first. Nothing here needs further interpretation, which is what
 * makes a frame portable to any 2D renderer.
 */
interface OrbFrame {
  dots: Dot[];
  lines: Line[];
}

type Projector = (x: number, y: number, z: number) => [number, number, number];

function lerp(a: number, b: number, f: number): number {
  return a + (b - a) * f;
}

function frac(x: number): number {
  return x - Math.floor(x);
}

/** Value noise on a 2D lattice — smooth, deterministic, cheap. */
function vnoise(x: number, y: number): number {
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  let fx = x - xi;
  let fy = y - yi;
  fx = fx * fx * (3 - 2 * fx);
  fy = fy * fy * (3 - 2 * fy);
  const a = hashD(xi, yi);
  const b = hashD(xi + 1, yi);
  const c = hashD(xi, yi + 1);
  const d = hashD(xi + 1, yi + 1);
  return a + (b - a) * fx + (c - a) * fy + (a - b - c + d) * fx * fy;
}

/** Deterministic hash in [0, 1). */
function hashD(a: number, b: number): number {
  const h = Math.sin(a * 12.9898 + b * 78.233) * 43758.5453;
  return h - Math.floor(h);
}

/** Stable directions on a unit sphere (Fibonacci lattice). */
function fibDir(i: number, n: number): [number, number, number] {
  const golden = Math.PI * (3 - Math.sqrt(5));
  const y = 1 - (2 * (i + 0.5)) / n;
  const rad = Math.sqrt(1 - y * y);
  const a = i * golden;
  return [rad * Math.cos(a), y, rad * Math.sin(a)];
}

/** Shortest signed angular distance, wrapped to (-π, π]. */
function angleDelta(a: number, b: number): number {
  return Math.atan2(Math.sin(a - b), Math.cos(a - b));
}

/** Shared spin + tilt + orthographic projection. */
function makeProj(yaw: number, tilt: number, cx: number, cy: number, scale: number): Projector {
  const st = Math.sin(tilt);
  const ct = Math.cos(tilt);
  const sy = Math.sin(yaw);
  const cyw = Math.cos(yaw);
  return (x, y, z) => {
    const x1 = x * cyw + z * sy;
    const z1 = -x * sy + z * cyw;
    const y1 = y * ct - z1 * st;
    const z2 = y * st + z1 * ct;
    return [cx + x1 * scale, cy - y1 * scale, z2];
  };
}

/** Paint grayscale depth as token-owned ink opacity on the page substrate. */
function paint(ctx: CanvasRenderingContext2D, dots: Dot[], ink: string, rMin = 0.3): void {
  ctx.fillStyle = ink;
  for (const d of dots) {
    const alpha = d.a ?? 1;
    const w = Math.min(1, Math.max(0, d.white));
    ctx.globalAlpha = alpha * (1 - w);
    ctx.beginPath();
    ctx.arc(d.x, d.y, d.r, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

/** Stroke pass for edge-based modes. Runs before `paint` so nodes sit on top. */
function paintLines(ctx: CanvasRenderingContext2D, lines: Line[], ink: string): void {
  ctx.strokeStyle = ink;
  for (const l of lines) {
    const alpha = l.a ?? 1;
    const w = Math.min(1, Math.max(0, l.white));
    ctx.globalAlpha = alpha * (1 - w);
    ctx.lineWidth = l.w;
    ctx.beginPath();
    ctx.moveTo(l.x1, l.y1);
    ctx.lineTo(l.x2, l.y2);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;
}

/**
 * Turn raw mode output into a finished frame: drop invisible marks, clamp
 * radii to the mode's floor, and z-sort far→near into draw order.
 *
 * This runs in the GEOMETRY step, not the painter, so a frame is a complete
 * set of draw instructions: every value is final and the array order is the
 * order to draw in. That is what lets the RN and SwiftUI ports share this
 * output verbatim — a port draws the list, it never re-derives anything —
 * and what lets the golden-vector tests compare numbers instead of pixels.
 */
function finalizeFrame(dots: Dot[], lines: Line[], rMin = 0.3): OrbFrame {
  const visible: Dot[] = [];
  for (const d of dots) {
    if ((d.a ?? 1) < 0.02) continue;
    d.r = Math.max(rMin, d.r);
    visible.push(d);
  }
  visible.sort((a, b) => a.z - b.z);
  return { dots: visible, lines: lines.filter((l) => (l.a ?? 1) >= 0.02) };
}

/** Paint a finished frame. Lines first, so nodes sit on top of their edges. */
function paintFrame(ctx: CanvasRenderingContext2D, frame: OrbFrame, ink: string): void {
  if (frame.lines.length) paintLines(ctx, frame.lines, ink);
  paint(ctx, frame.dots, ink);
}



/** Dot radii were tuned for a 300pt frame; sub-linear scaling keeps small
 * spinners legible. Lower pow = radii shrink less with size. */
function radiusScale(size: number, pow: number): number {
  return (size / 300) ** pow;
}

const TURN = Math.PI * 2;

function smoothE(x: number): number {
  return x * x * (3 - 2 * x);
}

/**
 * Smootherstep — zero first AND second derivative at both ends.
 *
 * Smoothstep stops with zero velocity but a sudden change in acceleration,
 * which the eye reads as a small jolt at the end of a long move. Over a
 * two-second morph that jolt is what makes the assembly feel like it halts
 * rather than arrives.
 */
function smootherE(x: number): number {
  return x * x * x * (x * (x * 6 - 15) + 10);
}

function clamp01(x: number): number {
  return x < 0 ? 0 : x > 1 ? 1 : x;
}

/**
 * What a logo mode renders before its artwork is baked. A fresh object each
 * time: a shared one would be handed to a caller that is free to mutate it.
 */
function empty(): OrbFrame {
  return { dots: [], lines: [] };
}

// --- shared painting ---------------------------------------------------

/**
 * Ink and radius for one projected logo dot.
 *
 * `zx` is the projected depth normalised to [0, 1] over the unit sphere,
 * exactly as the orb modes compute it, so the near/far falloff matches.
 * `edge` is the baked distance from the silhouette boundary: weighting ink
 * by it gives the mark internal structure that survives being viewed
 * face-on, where projected depth alone is nearly constant and the whole
 * thing would otherwise flatten to a single tone.
 */
function inkOf(o: Record<string, number | undefined>, zx: number, edge: number): number {
  const far = o.inkFar ?? 0.6;
  const span = o.inkSpan ?? 0.5;
  const rim = o.inkRim ?? 0.16;
  return far - span * zx - rim * (1 - edge);
}

// --- Scan: an evenly packed sphere, swept by a meridian ----------------

/**
 * easeInOutExpo — the CSS `cubic-bezier(0.87, 0, 0.13, 1)` curve.
 *
 * Near-still at both ends, very fast through the middle.
 */
function expoInOut(x: number): number {
  if (x <= 0) return 0;
  if (x >= 1) return 1;
  return x < 0.5 ? 2 ** (20 * x - 10) / 2 : (2 - 2 ** (-20 * x + 10)) / 2;
}

/**
 * The morph curve: smootherstep with a measured amount of expo mixed in.
 *
 * Pure expo was tried and works against what this transition needs. Its
 * flat tails mean the morph barely moves for the first and last third,
 * which reads as the mark pausing at each end — the exact pause being
 * designed out — while its violent middle covers most of the distance in a
 * few frames and reads as a snap. Slow AND stalled, which is the worst of
 * both.
 *
 * The blend keeps expo's character — a deliberate ease in, a confident
 * middle — without the dead zones. Duration does the rest: 300 dots
 * travelling across the frame need several times the 0.6s a CSS transform
 * on a single block would.
 */
function morphEase(x: number, expo: number): number {
  const smooth = x * x * x * (x * (x * 6 - 15) + 10);
  return smooth + (expoInOut(x) - smooth) * expo;
}

/**
 * Rotation that cruises: eased at both ends, constant in between.
 *
 * A plain smootherstep across a long span puts all the speed in the middle,
 * so the orb visibly surges and slows for no reason. What is wanted is a
 * turn that starts, holds a steady rate, and stops — the ramps are shaped,
 * the middle is linear, and the whole thing integrates to exactly 1.
 */
function cruise(x: number, edge: number): number {
  const a = Math.min(0.49, Math.max(0.001, edge));
  const v = 1 / (1 - a);
  if (x <= 0) return 0;
  if (x >= 1) return 1;
  if (x < a) {
    const u = x / a;
    return v * a * (u * u * u - (u * u * u * u) / 2);
  }
  if (x > 1 - a) {
    const u = (1 - x) / a;
    return 1 - v * a * (u * u * u - (u * u * u * u) / 2);
  }
  return v * (a * 0.5 + (x - a));
}

/** Where the cycle is, and what everything downstream reads off it. */
interface Beat {
  /** 0 = working form, 1 = the mark. */
  m: number;
  /** Whole turns completed; lands on an integer before the mark appears. */
  turns: number;
  /** Seconds into the working-form dwell — what `solve` and `scan` run on. */
  workT: number;
  local: number;
  cycle: number;
}

/**
 * The cycle: dwell in the working form, morph to the mark, morph back.
 *
 * Explicit phases rather than a derived envelope, because each turned out
 * to need its own duration, and deriving them from a single bell meant
 * tuning one by distorting the others. Nothing here is flat except the
 * dwell, which is the one pause that is actually wanted: the mark is
 * reached and immediately left, so the morph out begins the instant the
 * morph in completes.
 *
 * Rotation belongs to the working form. It runs across the dwell and eases
 * out partway through the morph in, so the orb is still turning as it
 * begins to become the mark, then settles. On the way back there is none at
 * all: a whole turn crammed into a short exit is the spin that reads as
 * frantic, and it buys nothing — the form is dissolving anyway.
 *
 * Because the count of turns is a whole number, the mark is always shown at
 * a whole revolution — dead face-on, every cycle — and the cycle closes
 * seamlessly with no accumulator and no state.
 */
function beatAt(
  t: number,
  dwell: number,
  morph: number,
  turns: number,
  settle: number,
  expo = 0.3
): Beat {
  const cycle = dwell + morph * 2;
  const local = t % cycle;

  // Rotation spans the dwell plus the first part of the morph in.
  const spinSpan = dwell + morph * settle;
  const spun = turns * cruise(Math.min(1, local / spinSpan), 0.22);

  if (local < dwell) return { m: 0, turns: spun, workT: local, local, cycle };
  const intoMorph = local - dwell;
  if (intoMorph < morph) {
    return { m: morphEase(intoMorph / morph, expo), turns: spun, workT: -1, local, cycle };
  }
  return { m: morphEase(1 - (intoMorph - morph) / morph, expo), turns: spun, workT: -1, local, cycle };
}

/**
 * Per-dot assembly, hashed rather than indexed.
 *
 * An index-ordered stagger sweeps the assembly across the mark like a wipe,
 * which reads as a progress bar. Hashed, the mark condenses out of the
 * cloud all at once.
 */
function dotAssembly(i: number, m: number, stagger: number): number {
  return smoothE(clamp01(m * (1 + stagger) - hashD(i, 3.1) * stagger));
}

// --- Work: logo → a thread wound into a knot → logo --------------------



/**
 * The mark becomes a barrel of stacked rings that draws tall and narrow,
 * then settles short and wide.
 *
 * Two versions failed for opposite reasons. Pulsing the logo a few percent
 * in place was invisible at icon size. A deformed sphere was visible but
 * shared its whole silhouette with `thinking`'s orb — the motions differed
 * and the shapes did not, which at a glance is the same thing as having one
 * state twice.
 *
 * Stacked rings are structurally different from every other form here:
 * open, layered, and obviously made of parts. And the pulse is not a scale
 * — height and radius move in OPPOSITE directions, so the volume stays
 * roughly constant and the object reads as something drawing air rather
 * than something being zoomed. That antiphase is the whole trick; a body
 * that simply grows and shrinks reads as a beating heart, not a breath.
 */
const frameLogoWait: ModeFrame = (size, t, o, logo) => {
  if (!logo) return empty();
  const { p, e, n } = logo.points;
  const seats = logo.seats;
  const cx = size / 2;
  const R = (size / 2) * 0.82;
  const rs = radiusScale(size, o.rsPow ?? 0.6);

  const b = beatAt(t, o.dwell ?? 5.5, o.morph ?? 1.9, o.turns ?? 0, o.settle ?? 0.1, o.expo ?? 0.3);
  const m = b.m;
  const c = 1 - m;

  // Held tilt, so the rings always read as a stack of ellipses. Seen
  // straight on they collapse into concentric circles and the layering —
  // the thing that makes this not a ball — disappears.
  const pt = makeProj(
    (o.yawAmp ?? 0.22) * Math.sin(t * (o.yawRate ?? 0.3)) * c,
    (o.tilt ?? 0.42) * c,
    cx,
    cx,
    R
  );

  const rings = Math.max(3, Math.round(o.rings ?? 9));
  const perRing = Math.ceil(n / rings);
  // Antiphase: in as it lengthens, out as it widens.
  const breath = Math.sin(t * (o.breatheRate ?? 0.75));
  const amp = o.breatheAmp ?? 0.2;
  const height = (o.height ?? 1.5) * (1 + amp * breath);
  const wide = (o.wide ?? 0.82) * (1 - amp * 0.72 * breath);
  const spin = t * (o.spin ?? 0.16);

  const dots: Dot[] = [];
  for (let i = 0; i < n; i++) {
    const seat = seats[i]!;
    const ring = seat % rings;
    const u = rings > 1 ? ring / (rings - 1) - 0.5 : 0;

    // Barrel profile: widest at the middle, tapering at both ends, so the
    // stack has a body rather than reading as a cylinder.
    const taper = Math.cos(u * Math.PI * (o.taper ?? 0.78));
    const rad = wide * taper;
    const ang = (Math.floor(seat / rings) / perRing) * Math.PI * 2 + spin;

    const bx = Math.cos(ang) * rad;
    const by = u * height;
    const bz = Math.sin(ang) * rad;

    const lx = p[i * 3]!;
    const ly = p[i * 3 + 1]!;
    const lz = p[i * 3 + 2]!;
    const x = lx + (bx - lx) * c;
    const y = ly + (by - ly) * c;
    const z3 = lz + (bz - lz) * c;

    const [px, py, z] = pt(x, y, z3);
    const zx = clamp01((z + 1) / 2);
    // The widest rings read brightest, so the exhale is carried by ink as
    // well as by shape.
    const loud = clamp01(taper);
    dots.push({
      x: px,
      y: py,
      z,
      r: ((o.rBase ?? 0.55) + (o.rDepth ?? 1.4) * zx + (o.loudR ?? 0.25) * loud * c) * rs,
      white: inkOf(o, zx, e[i]! * m + (1 - m)) - (o.loudInk ?? 0.12) * loud * c
    });
  }
  return finalizeFrame(dots, [], o.rMin);
};

